action.code:
int curLen = 0;
TreeNode* node = root;
for (int i = 0; i < encLen; ++i) {
    int bit = encoded[i];
    if (bit == 0) {
        node = node->left;
    } else {
        node = node->right;
    }
    if (node->left == nullptr && node->right == nullptr) {
        decoded[curLen] = node->symbol;
        ++curLen;
        node = root;
    }
}
decLen = curLen;

